    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
}

.close-btn:hover {
    background: var(--danger);
    color: var(--bg-primary);
}

.modal-body {
    padding: 1.5rem;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.setting-group label {
    display: block;
    font-weight: 900;
    color: var(--text-primary);
    margin-bottom: 0.5rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.help-text {
    display: block;
    margin-top: 0.5rem;
    font-size: 0.875rem;
    color: var(--text-muted);
    font-weight: 700;
}

.profile-upload-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1rem;
    padding: 1rem;
    border: 3px dashed var(--border);
    background: var(--bg-tertiary);
}

.profile-preview {
    width: 120px;
    height: 120px;
    border: 4px solid var(--border);
    background: var(--bg-secondary);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.profile-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.profile-preview-placeholder {
    font-size: 3rem;
}

.file-input-label {
    padding: 0.75rem 1.5rem;
    border: 3px solid var(--border);
    background: var(--text-primary);
    color: var(--bg-primary);
    cursor: pointer;
    font-weight: 900;
    text-transform: uppercase;
    transition: all 0.2s ease;
}

.file-input-label:hover {
    transform: translate(-2px, -2px);
    box-shadow: 4px 4px 0 var(--border);
}

.file-input-label:active {
    transform: translate(0, 0);
    box-shadow: none;
}

input[type="file"] {
    display: none;
}

.modal-footer {
    padding: 1.5rem;
    border-top: 3px solid var(--border);
    background: var(--bg-tertiary);
}

/* ============================================
   Toast Notification - BRUTALISM
   ============================================ */

.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: var(--bg-secondary);
    color: var(--text-primary);
    padding: 1rem 1.5rem;
    border: 4px solid var(--border);
    z-index: 2000;
    font-weight: 900;
    text-transform: uppercase;
    max-width: 300px;
}

.toast.hidden {
    display: none;
}

.toast.success {
    border-color: var(--success);
    background: var(--success-bg);
}

.toast.error {
    border-color: var(--danger);
    background: var(--danger-bg);
}

.toast.warning {
    border-color: var(--warning);
    background: var(--warning-bg);
}

/* ============================================
   Responsive Design - BRUTALISM
   ============================================ */

@media (max-width: 968px) {
    .content-grid {
        grid-template-columns: 1fr;
    }

    .greeting {
        font-size: 1.5rem;
    }

    .time {
        font-size: 2.5rem;
    }

    .timer-display {
        font-size: 3rem;
    }

    .header-container {
        padding: 0 1rem;
    }

    .container {
        padding: 1rem;
    }
}

@media (max-width: 640px) {
    .add-task-form {
        flex-direction: column;
    }

    .input-field,
    .select-field {
        width: 100%;
    }

    .task-stats {
        flex-direction: column;
        gap: 1rem;
    }

    .timer-controls {
        flex-direction: column;
    }

    .timer-controls .btn {
        width: 100%;
    }

    .quicklinks-list {
        grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
    }

    .greeting-card {
        padding: 2rem 1rem;
    }

    .toast {
        left: 1rem;
        right: 1rem;
        bottom: 1rem;
    }

    .card::after {
        display: none;
    }

    .logo {
        font-size: 1rem;
        letter-spacing: 1px;
    }

    .header-controls {
        gap: 0.25rem;
    }

    .icon-btn,
    .profile-pic-container {
        width: 40px;
        height: 40px;
        font-size: 1rem;
    }
}

/* ============================================
   Utility Classes
   ============================================ */

.hidden {
    display: none !important;
}

.text-center {
    text-align: center;
}

/* ============================================
   Accessibility - BRUTALISM
   ============================================ */

*:focus-visible {
    outline: 3px solid var(--accent);
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

